```c
#include <stdio.h>
#include <string.h>

int main(void) {
    int N, M, K;
    if (scanf("%d %d %d", &N, &M, &K) != 3) return 0;

    char pattern[505];
    scanf("%s", pattern);

    int hash_pos[505];
    int hc = 0;
    for (int i = 0; i < N; i++) {
        if (pattern[i] == '#') {
            hash_pos[hc++] = i;
        }
    }

    char unique[505][26];
    int d[505];

    for (int i = 0; i < M; i++) {
        char word[30];
        scanf("%s", word);

        int seen[26] = {0};
        for (int j = 0; j < K; j++) {
            seen[word[j] - 'a'] = 1;
        }

        int cnt = 0;
        for (int c = 0; c < 26; c++) {
            if (seen[c]) {
                unique[i][cnt++] = (char)('a' + c);
            }
        }
        d[i] = cnt;
    }

    long long P;
    scanf("%lld", &P);

    const long long CAP = 1000000001LL;
    long long suffix[505];
    suffix[M] = 1;

    for (int i = M - 1; i >= 0; i--) {
        suffix[i] = suffix[i + 1] * d[i];
        if (suffix[i] > CAP) suffix[i] = CAP;
    }

    char result[505];
    strcpy(result, pattern);

    for (int i = 0; i < M; i++) {
        long long rem = suffix[i + 1];
        long long idx = (P - 1) / rem;
        result[hash_pos[i]] = unique[i][idx];
        P = (P - 1) % rem + 1;
    }

    result[N] = '\0';
    printf("%s\n", result);

    return 0;
}
```

